package com.adib.maintenance;
import android.graphics.*;import android.view.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.lang.reflect.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h800dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) public class FocusedViewsVisualTest{
 void set(MainActivity a,String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(MainActivity a,String n)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(a);}void call(MainActivity a,String n)throws Exception{Method m=MainActivity.class.getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 JSONArray tasks()throws Exception{JSONArray rows=new JSONArray();for(int i=0;i<8;i++)rows.put(new JSONObject().put("id","task"+i).put("title",new String[]{"Desktop təmizləmək","SAP bağlamaq","Avadanlığın yoxlanması","Mallar aktlaşdırmaq"}[i%4]).put("priority","Medium").put("status","Not started").put("eisenhower",new String[]{"urgent-important","not-urgent-important","urgent-unimportant","not-urgent-unimportant"}[i%4]).put("date","2026-10-12T09:00:00").put("dateEnd","2026-10-12T09:40:00"));return rows;}
 void capture(View v,String name)throws Exception{v.measure(View.MeasureSpec.makeMeasureSpec(390,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY));v.layout(0,0,390,760);Bitmap b=Bitmap.createBitmap(390,760,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File dir=new File("/data/adib-fullscreen/previews");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void nativeScreens()throws Exception{JSONObject old=AccountSession.user;TaskReminderActions.Transport prior=EmployeeChats.transport;AccountSession.user=new JSONObject().put("id","visual").put("name","Ilqar").put("role","admin");EmployeeChats.transport=(m,p,b)->new JSONObject().put("available",true).put("employees",new JSONArray()).put("threads",new JSONArray());try{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"personalTasks",tasks());set(a,"screen","home");call(a,"render");capture((View)get(a,"root"),"android-home");set(a,"mode","matrix");set(a,"screen","list");call(a,"render");capture((View)get(a,"root"),"android-matrix");set(a,"chatRequestRunning",true);JSONArray threads=new JSONArray();for(int i=0;i<4;i++)threads.put(new JSONObject().put("taskId","task"+i).put("title",tasks().getJSONObject(i).optString("title")).put("comments",new JSONArray().put(new JSONObject().put("id","m"+i).put("authorName","Huseyn").put("text","Yoxlanıldı").put("createdAt","2026-10-12T10:00:00Z"))));a.getPreferences(0).edit().putString("chat_threads_cache",threads.toString()).commit();call(a,"showChat");capture((View)get(a,"chatScreenRoot"),"android-discussions");TaskCalendarActivity c=Robolectric.buildActivity(TaskCalendarActivity.class).get();c.tasks=tasks();c.selected="2026-10-12";c.mode="day";c.message="Saxlanan tapşırıqlar";c.phone=new CalendarPhoneUi(c);c.phone.render();capture(c.root,"android-calendar");assertEquals(View.GONE,c.status.getVisibility());}finally{AccountSession.user=old;EmployeeChats.transport=prior;}}
}
